/* ---------- CLEAR DATA (Reports) : test / real reset ---------- */
const canClr=()=>me().n==='Tola168';
function clrHTML(){
 if(!canClr())return '';
 return `<div class="card" id="clr" style="margin-top:18px;border:2px solid var(--bad)">
 <div class="rp-sec" style="color:var(--bad)">⚠ Clear data — Test / Real</div>
 <p style="margin:0 0 10px;color:var(--mut);font-size:14px">Only Tola168 can see and use this. Use it to wipe the test money and tickets before going live, or to start fresh. A backup file is downloaded automatically first. <b>This cannot be undone.</b></p>
 <div class="f">
  <div><label>What to clear</label><select id="clr_w">
   <option value="money">Money &amp; tickets only (bank balances, tickets, deposits)</option>
   <option value="all">Money, tickets &amp; draw results</option>
   <option value="full">Everything (+ activity log) — keep users &amp; settings</option>
  </select></div>
  <div><label>Which company</label><select id="clr_c"><option value="cur">${esc(S.co)} (current)</option><option value="both">Both companies</option></select></div>
  <div><label>Type <b>CLEAR</b> to confirm</label><input id="clr_t" placeholder="CLEAR" autocomplete="off"></div>
  <div class="rs-btn"><button class="btn dng" id="clr_b">Clear data now</button></div>
 </div></div>`}
function clrBackup(){try{const n=new Date(),nm='Lucky89-before-clear-'+ymd(n)+'-'+pad(n.getHours())+pad(n.getMinutes())+'.json',bl=new Blob([JSON.stringify(S)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(bl);a.download=nm;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),3000);return true}catch(e){return false}}
function clrInit(){const b=$('#clr_b');if(!b)return;b.onclick=()=>{
 if(!canClr())return toast('Only Tola168 can clear data');
 if(($('#clr_t').value||'').trim().toUpperCase()!=='CLEAR')return toast('Type CLEAR to confirm');
 const w=$('#clr_w').value,both=$('#clr_c').value==='both',cos=both?COS.slice():[S.co];
 if(!confirm('Clear '+(w==='money'?'money & tickets':w==='all'?'money, tickets & results':'ALL data except users/settings')+' for '+(both?'BOTH companies':S.co)+'?\n\nA backup file will download first. This cannot be undone.'))return;
 clrBackup();
 cos.forEach(co=>{const d=S.d[co]||(S.d[co]={t:[],r:[],n:0});d.t=[];d.r=[];d.n=0});
 if(w==='all'||w==='full'){S.res={};S.kt={};S.lk=null;S.lastRes=null}
 if(w==='full'){S.log=[]}
 lg('Cleared data ('+w+') for '+(both?'both companies':S.co));
 sv();toast('Data cleared ✓');rep()}}

