 ['rg','mk','tm','bk','us'].forEach(k=>$('#f_'+k).onchange=e=>{F[k]=e.target.value;rt()});['q','w'].forEach(k=>$('#f_'+k).oninput=e=>{F[k]=e.target.value;rt()});
