 <div class="rp-tb"><h4>Tickets <span>(${t.length})</span></h4><div class="rp-ch">${RPST.map(c=>`<button class="${(F.st||'')===c[0]?'on':''}" onclick="F.st='${c[0]}';rt()">${c[1]} <i>${cnt(c[0])}</i></button>`).join('')}</div><button class="btn sm" id="csv">Export CSV</button></div>
