/* ---------- payment received + edit ticket ---------- */
const isRO=()=>false,EDIT_MIN=15;
/* minutes left until editing locks (draw time minus 15 min); <=0 means locked */
const editLeft=t=>{const p=t.dt.split('-').map(Number),draw=new Date(p[0],p[1]-1,p[2],0,tmin(t.tm),0);return(draw-new Date())/60000-EDIT_MIN};
const canEdit=t=>t.st==='open'&&t.pay==null&&editLeft(t)>0;
