 $('#a_am').oninput=ap;$('#a_am').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();$('#a_rm').focus()}};$('#a_rm').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();$('#a_ad').click()}};
