/* ---------- LOGIN: lottery matrix rain ---------- */
function matrixRain(m){const cv=m.querySelector('canvas.mx');if(!cv)return;const cx=cv.getContext('2d');if(!cx)return;
 const CH='0123456789០១២៣៤៥៦៧៨៩ABCDFINO89$៛'.split('');let W,H,fs,cols,drops,spd,tone,dpr;
 const rz=()=>{dpr=Math.min(window.devicePixelRatio||1,2);W=m.clientWidth||innerWidth;H=m.clientHeight||innerHeight;cv.width=W*dpr;cv.height=H*dpr;cv.style.width=W+'px';cv.style.height=H+'px';cx.setTransform(dpr,0,0,dpr,0,0);fs=W<600?16:20;cols=Math.ceil(W/fs);drops=Array.from({length:cols},()=>Math.random()<.7?Math.random()*(H/fs)*.9:Math.random()*-25);spd=Array.from({length:cols},()=>.4+Math.random()*.8);tone=Array.from({length:cols},()=>Math.random()<.16?1:0);cx.fillStyle='#030a10';cx.fillRect(0,0,W,H)};
 rz();addEventListener('resize',rz);
 const still=matchMedia('(prefers-reduced-motion:reduce)').matches;let last=0;
 const draw=t=>{if(!m.isConnected){removeEventListener('resize',rz);return}
  if(t-last>38||still){last=t;cx.fillStyle='rgba(3,10,16,.09)';cx.fillRect(0,0,W,H);cx.font='700 '+fs+'px "Courier New",monospace';cx.textAlign='center';
   for(let i=0;i<cols;i++){const y=drops[i]*fs,x=i*fs+fs/2,g=tone[i];
    if(y>-fs){const c=CH[(Math.random()*CH.length)|0];
     cx.fillStyle=g?'rgba(255,170,60,.5)':'rgba(70,200,215,.42)';cx.fillText(CH[(Math.random()*CH.length)|0],x,y-fs);
     cx.shadowColor=g?'#ff9a3c':'#3de0e6';cx.shadowBlur=14;cx.fillStyle=g?'#ffe2b8':'#e6fcff';cx.fillText(c,x,y);cx.shadowBlur=0}
    drops[i]+=spd[i];if(y>H+fs*6&&Math.random()>.975){drops[i]=Math.random()*-20;spd[i]=.35+Math.random()*.75}}
   if(still&&t>200)return}
  requestAnimationFrame(draw)};
 requestAnimationFrame(draw)}


