const CL={db:null,sig:{},ready:false,got:false,tm:null,busy:false,again:false};
const hk=x=>{let a=5381,b=52711;for(let i=0;i<x.length;i++){const c=x.charCodeAt(i);a=((a<<5)+a+c)|0;b=(((b<<5)+b)^c)|0}return(a>>>0).toString(36)+(b>>>0).toString(36)+x.length.toString(36)};
const cst=(k,t)=>{const e=document.getElementById('cld');if(!e)return;e.dataset.s=k;e.textContent=t;e.title=t};
const cens=co=>S.d[co]||(S.d[co]={t:[],r:[],n:0});
function cseq(d,dt){const key=(dt||today()).replace(/-/g,'');let m=0;(d.t||[]).forEach(t=>{const p=String(t.id).split('-');if(p[1]===key){const n=parseInt(p[2],10);if(n>m)m=n}});return m}
function cents(){const m={};
 COS.forEach(co=>{const d=S.d[co];if(!d)return;
  (d.t||[]).forEach(t=>{m['t_'+t.id]=JSON.stringify({co,t})});
  (d.r||[]).forEach(r=>{m['r_'+PF[co]+'_'+r.id]=JSON.stringify({co,r})})});
 Object.keys(S.res||{}).forEach(k=>{m['x_'+hk(k)]=JSON.stringify({k,v:S.res[k],t:(S.kt&&S.kt[k])||0})});
 (S.users||[]).forEach(u=>{m['u_'+hk(String(u.n).toLowerCase())]=JSON.stringify(u)});
 m['c_main']=JSON.stringify(S.cfg||{});
 (S.log||[]).forEach(l=>{m['g_'+l.ts+'_'+hk(String(l.us)+String(l.m))]=JSON.stringify(l)});
 return m}
function cset(id,o){const p=id.slice(0,2);
 if(p==='t_'){if(!o||!COS.includes(o.co)||!o.t||!o.t.id)return false;const d=cens(o.co);o.t.co=o.co;const i=d.t.findIndex(x=>x.id===o.t.id);
  if(i>=0){const lo=d.t[i];
   if(lo.ts&&o.t.ts&&lo.ts!==o.t.ts){
    if(o.t.ts<lo.ts){d.t[i]=o.t;lo.id=PF[o.co]+'-'+String(lo.dt).replace(/-/g,'')+'-'+String(cseq(d,lo.dt)+1).padStart(5,'0');d.t.push(lo);d.t.sort((a,b)=>String(b.ts).localeCompare(String(a.ts)))}
   }else d.t[i]=o.t}
  else{d.t.push(o.t);d.t.sort((a,b)=>String(b.ts).localeCompare(String(a.ts)))}return true}
 if(p==='r_'){if(!o||!COS.includes(o.co)||!o.r)return false;const d=cens(o.co),i=d.r.findIndex(x=>x.id===o.r.id);if(i>=0)d.r[i]=o.r;else{d.r.push(o.r);d.r.sort((a,b)=>String(b.ts).localeCompare(String(a.ts)))}return true}
 if(p==='x_'){if(!o||!o.k)return false;S.res=S.res||{};S.kt=S.kt||{};S.res[o.k]=o.v;if(o.t)S.kt[o.k]=o.t;const q=o.k.split('|');if(!S.lk||(o.t||0)>(S.lk.t||0))S.lk={mk:q[0],dt:q[1],tm:q[2],t:o.t||Date.now()};return true}
 if(p==='u_'){if(!o||!o.n)return false;S.users=S.users||[];const i=S.users.findIndex(x=>String(x.n).toLowerCase()===String(o.n).toLowerCase());if(i>=0)S.users[i]=o;else S.users.push(o);return true}
 if(id==='c_main'){if(!o||typeof o!=='object')return false;S.cfg=Object.assign(S.cfg||{},o);R2=S.cfg.r2;R3=S.cfg.r3;return true}
 if(p==='g_'){if(!o||!o.ts)return false;S.log=S.log||[];if(!S.log.some(l=>l.ts===o.ts&&l.us===o.us&&l.m===o.m)){S.log.push(o);S.log.sort((a,b)=>b.ts-a.ts);S.log=S.log.slice(0,50)}return true}
 return false}
function cdel(id,o){const p=id.slice(0,2);
 if(p==='t_'){const d=S.d[o.co];if(!d)return false;const n=d.t.length;d.t=d.t.filter(x=>x.id!==o.t.id);return d.t.length!==n}
 if(p==='r_'){const d=S.d[o.co];if(!d)return false;const n=d.r.length;d.r=d.r.filter(x=>x.id!==o.r.id);return d.r.length!==n}
 if(p==='x_'){if(S.res&&S.res[o.k]){delete S.res[o.k];if(S.kt)delete S.kt[o.k];if(S.lk&&[S.lk.mk,S.lk.dt,S.lk.tm].join('|')===o.k)S.lk=null;return true}return false}
 if(p==='u_'){const n=S.users.length;S.users=S.users.filter(x=>String(x.n).toLowerCase()!==String(o.n).toLowerCase());return S.users.length!==n}
 if(p==='g_'){const n=S.log.length;S.log=S.log.filter(l=>!(l.ts===o.ts&&l.us===o.us&&l.m===o.m));return S.log.length!==n}
 return false}
function capply(ch){let dirty=false;
 ch.forEach(c=>{const id=c.doc.id;
  if(c.type==='removed'){const old=CL.sig[id];delete CL.sig[id];if(old==null)return;try{if(cdel(id,JSON.parse(old)))dirty=true}catch(e){}return}
  const dt=c.doc.data()||{},j=dt.j;if(typeof j!=='string'||CL.sig[id]===j)return;
  let o;try{o=JSON.parse(j)}catch(e){return}
  if(cset(id,o)){CL.sig[id]=j;dirty=true}});
 return dirty}
let CRT=null;
function cre(){clearTimeout(CRT);CRT=setTimeout(()=>{try{if(!me().n)return;const a=document.activeElement;if((view==='dash'||view==='rep')&&!(a&&/^(INPUT|SELECT|TEXTAREA)$/.test(a.tagName))&&!document.getElementById('md'))go()}catch(e){}},500)}
function cloudPush(){try{if(!CL.db||!CL.ready)return;clearTimeout(CL.tm);CL.tm=setTimeout(cflush,600)}catch(e){}}
async function cflush(){
 if(CL.busy){CL.again=true;return}
 CL.busy=true;
 try{
  const cur=cents(),ops=[];
  for(const id in cur)if(CL.sig[id]!==cur[id])ops.push([id,cur[id]]);
  for(const id in CL.sig)if(!(id in cur))ops.push([id,null]);
  if(ops.length){cst('sync','☁ Saving…');
   for(let i=0;i<ops.length;i+=10){
    await Promise.all(ops.slice(i,i+10).map(async([id,j])=>{
     const ref=CL.db.doc('l89/'+id);
     if(j===null){await ref.delete();delete CL.sig[id];return}
     const prev=CL.sig[id];CL.sig[id]=j;
     try{await ref.set({j,u:S.us||'',t:Date.now()})}catch(e){if(prev===undefined)delete CL.sig[id];else CL.sig[id]=prev;throw e}}))}}
  cst('ok','☁ Cloud saved');
 }catch(e){const c=e&&e.code,ro=c==='not_granted'||c==='revoked'||c==='capability_disabled';cst('err',ro?'☁ View only — no permission to save':'☁ Cloud error — retrying');if(!ro)setTimeout(cloudPush,15000)}
 CL.busy=false;if(CL.again){CL.again=false;cloudPush()}}
async function cloudInit(){
 try{
  if(!window.claude||!window.claude.use){cst('off','☁ This device only');return}
  const db=await window.claude.use('db');
  if(!db){cst('off','☁ Sign in to Claude to sync');return}
  CL.db=db;cst('sync','☁ Connecting…');
  const fin=()=>{if(CL.ready)return;CL.ready=true;cst('ok','☁ Cloud connected');cloudPush()};
  setTimeout(()=>{if(CL.got&&!CL.ready)fin()},8000);
  db.collection('l89').onSnapshot(snap=>{CL.got=true;
   const ch=snap.docChanges().filter(c=>!(c.doc.metadata&&c.doc.metadata.hasPendingWrites));
   if(capply(ch)){try{localStorage.setItem('lmp2',JSON.stringify(S))}catch(e){}cre();if(CL.ready)cloudPush()}
   if(!CL.ready&&!(snap.metadata&&snap.metadata.fromCache))fin()},
   e=>{cst('err','☁ Cloud unavailable')});
 }catch(e){cst('off','☁ This device only')}}
/*CLOUD-END*/

cloudInit();

